// Cross-engine check: the TypeScript Arena engine used by the Interactive Web Preview must reproduce matches played by
// the authoritative C# engine (fixtures generated by backend/tests/PetStar.Rules.Tests/ArenaFixtureTests.cs).
import { describe, expect, it } from 'vitest';
import fixtures from './__fixtures__/arena-fixtures.json';
import { decide } from './ai';
import { apply, create, mustAct, timeout } from './engine';
import { ArenaRules, digest, type ArenaAction, type ArenaDeckCard, type ArenaRulesData } from './model';

interface Case { seed: string; pve: boolean; aiOnly: boolean; decks: ArenaDeckCard[][]; actions: { p: number; a: ArenaAction | null }[]; winner: number | null; endReason: string; turn: number; points: number[]; log: string[] }

async function loadRules(): Promise<ArenaRules> {
  const fsName = 'node:fs';
  const { readFileSync } = await import(/* @vite-ignore */ fsName) as { readFileSync: (f: string, e: string) => string };
  return new ArenaRules(JSON.parse(readFileSync('public/data/arena_cards.json', 'utf8')) as ArenaRulesData);
}
const cases = (fixtures as unknown as { version: string; cases: Case[] }).cases;
const fresh = (rules: ArenaRules, c: Case) =>
  create(rules, { name: 'Blue', deck: c.decks[0], energyTypes: [] }, { name: 'Red', deck: c.decks[1], energyTypes: [] }, BigInt(c.seed), c.pve);

describe('arena: TypeScript engine = C# engine', () => {
  it('ships the definitions version the fixtures were made with', async () => {
    const rules = await loadRules();
    expect(rules.version).toBe((fixtures as { version: string }).version);
    expect(rules.data.cards.filter((c) => c.kind === 'pet')).toHaveLength(215);
  });

  it.each(cases.map((c, i) => [i, c] as const))('replays case %i action by action to the identical log', async (_i, c) => {
    const rules = await loadRules();
    const st = fresh(rules, c);
    for (const { p, a } of c.actions) { if (p < 0) timeout(rules, st); else apply(rules, st, p, a!); }
    expect(st.log.map(digest)).toEqual(c.log);
    expect(st.winner).toBe(c.winner);
    expect(st.endReason).toBe(c.endReason);
    expect(st.players.map((x) => x.points)).toEqual(c.points);
  });

  it.each(cases.filter((c) => c.aiOnly).map((c, i) => [i, c] as const))('the TypeScript AI makes the same choices (case %i)', async (_i, c) => {
    const rules = await loadRules();
    const st = fresh(rules, c);
    for (let n = 0; st.phase !== 'finished' && n < 4000; n++) {
      const p = mustAct(st, 0) ? 0 : 1;
      apply(rules, st, p, decide(rules, st, p));
    }
    expect(st.log.map(digest)).toEqual(c.log);
  });
});
